55	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const isKnownItemType = (type: string): boolean =>
68	  type in BASE_PREMIUM_BY_ITEM_TYPE;
69	
70	const rejectUnknownItemTypes = (items: readonly Item[]): void => {
71	  const unknownItem = items.find((item) => !isKnownItemType(item.type));
72	
73	  if (unknownItem !== undefined) {
74	    throw new Error(`Unknown item type: ${unknownItem.type}`);
75	  }
76	};
77	
78	const itemBasePremiumOf = (item: Item): number =>
79	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
80	
81	const BLOCK_PREMIUM = 60;
82	const BLOCK_SIZE = 3;
83	
84	const itemTypesOf = (items: readonly Item[]): readonly string[] => [
85	  ...new Set(items.map((item) => item.type)),
86	];
87	
88	const itemsGroupedByType = (
89	  items: readonly Item[],
90	): readonly (readonly Item[])[] =>
91	  itemTypesOf(items).map((type) => items.filter((item) => item.type === type));
92	
93	// A component block is a discount on exactly BLOCK_SIZE items of the same type.
94	const sameTypeBasePremiumOf = (sameTypeItems: readonly Item[]): number =>
95	  sameTypeItems.length === BLOCK_SIZE
96	    ? BLOCK_PREMIUM
97	    : sumOf(sameTypeItems, itemBasePremiumOf);
98	
99	const CURSED_SURCHARGE_RATE = 0.5;
100	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
101	const HIGH_ENCHANTMENT_THRESHOLD = 5;
102	
103	const isCursed = (item: Item): boolean => item.cursed === true;
104	
105	const isHighlyEnchanted = (item: Item): boolean =>
106	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
107	
108	interface Surcharge {
109	  readonly appliesTo: (item: Item) => boolean;
110	  readonly rate: number;
111	}
112	
113	const SURCHARGES: readonly Surcharge[] = [
114	  { appliesTo: isCursed, rate: CURSED_SURCHARGE_RATE },
115	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
116	];
117	
118	const surchargeRateOf = (item: Item): number =>
119	  sumOf(SURCHARGES, (surcharge) =>
120	    surcharge.appliesTo(item) ? surcharge.rate : 0,
121	  );
122	
123	const itemSurchargeOf = (item: Item): number =>
124	  itemBasePremiumOf(item) * surchargeRateOf(item);
125	
126	const policyBasePremiumOf = (items: readonly Item[]): number =>
127	  sumOf(itemsGroupedByType(items), sameTypeBasePremiumOf);
128	
129	const policySurchargeOf = (items: readonly Item[]): number =>
130	  sumOf(items, itemSurchargeOf);
131	
132	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
133	
134	const firstInsuranceSurchargeOf = (basePremium: number): number =>
135	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
136	
137	const LOYALTY_DISCOUNT_RATE = 0.2;
138	const LOYALTY_YEARS_THRESHOLD = 2;
139	
140	const loyaltyDiscountOf = (basePremium: number, customer: Customer): number =>
141	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
142	    ? basePremium * LOYALTY_DISCOUNT_RATE
143	    : 0;
144	
145	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
146	
147	const followUpDiscountOf = (
148	  basePremium: number,
149	  previousQuoteCount: number,
150	): number =>
151	  previousQuoteCount > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
152	
153	const exactPremiumBeforeFeeOf = (
154	  items: readonly Item[],
155	  customer: Customer,
156	  previousQuoteCount: number,
157	): number => {
158	  const basePremium = policyBasePremiumOf(items);
159	
160	  return (
161	    basePremium +
162	    policySurchargeOf(items) +
163	    firstInsuranceSurchargeOf(basePremium) -
164	    loyaltyDiscountOf(basePremium, customer) -
165	    followUpDiscountOf(basePremium, previousQuoteCount)
166	  );
167	};
168	
169	const PROCESSING_FEE = 5;
170	
171	const quotePremiumOf = (
172	  items: readonly Item[],
173	  customer: Customer,
174	  previousQuoteCount: number,
175	): number => {
176	  rejectUnknownItemTypes(items);
177	
178	  return Math.ceil(
179	    exactPremiumBeforeFeeOf(items, customer, previousQuoteCount) +
180	      PROCESSING_FEE,
181	  );
182	};
183	
184	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
185	  sword: 1000,
186	  amulet: 600,
187	  rune: 250,
188	};
189	
190	const DEDUCTIBLE = 100;
191	const CAP_FACTOR = 2;
192	
193	const itemInsuranceValueOf = (item: Item): number =>
194	  INSURANCE_VALUE_BY_ITEM_TYPE[item.type];
195	
196	const insuranceSumOf = (items: readonly Item[]): number =>
197	  sumOf(items, itemInsuranceValueOf);
198	
199	const MASTER_ENCHANTMENT_THRESHOLD = 8;
200	const MASTER_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
201	const FULL_REIMBURSEMENT_RATE = 1;
202	
203	const isMasterEnchanted = (item: Item): boolean =>
204	  (item.enchantment ?? 0) >= MASTER_ENCHANTMENT_THRESHOLD;
205	
206	// Dragon material needs no branch of its own: it is reimbursed in full, which
207	// is already the default rate. Master enchantment overrides that default.
208	const reimbursementRateOf = (item: Item): number =>
209	  isMasterEnchanted(item)
210	    ? MASTER_ENCHANTMENT_REIMBURSEMENT_RATE
211	    : FULL_REIMBURSEMENT_RATE;
212	
213	const damagedItemOf = (damage: Damage, items: readonly Item[]): Item =>
214	  items.find((item) => item.type === damage.itemType) as Item;
215	
216	const damagePayoutOf = (damage: Damage, items: readonly Item[]): number =>
217	  damage.amount * reimbursementRateOf(damagedItemOf(damage, items)) -
218	  DEDUCTIBLE;
219	
220	const capOf = (insuredItems: readonly Item[]): number =>
221	  insuranceSumOf(insuredItems) * CAP_FACTOR;
222	
223	const entitledPayoutOf = (
224	  incident: Incident,
225	  insuredItems: readonly Item[],
226	): number =>
227	  sumOf(incident.damages, (damage) => damagePayoutOf(damage, insuredItems));
228	
229	// The cap limits what a policy pays out over its lifetime, so a claim never
230	// pays more than the cap left at the time it is made.
231	const claimResultOf = (
232	  step: ClaimStep,
233	  policies: readonly QuoteStep[],
234	  remainingCap: number,
235	): ClaimResult => {
236	  const entitledPayout = entitledPayoutOf(
237	    step.incident,
238	    policies[step.policy].items,
239	  );
240	  const payout = Math.min(entitledPayout, remainingCap);
241	
242	  return { payout, remainingCap: remainingCap - payout };
243	};
244	
245	const quoteResultOf = (
246	  step: QuoteStep,
247	  customer: Customer,
248	  previousQuoteSteps: readonly QuoteStep[],
249	): QuoteResult => ({
250	  premium: quotePremiumOf(step.items, customer, previousQuoteSteps.length),
251	});
252	
253	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
254	
255	const quoteStepsOf = (steps: readonly Step[]): readonly QuoteStep[] =>
256	  steps.filter(isQuoteStep);
257	
258	const quoteStepsBefore = (
259	  steps: readonly Step[],
260	  stepIndex: number,
261	): readonly QuoteStep[] => quoteStepsOf(steps.slice(0, stepIndex));
262	
263	// The state a scenario carries from one step to the next: the results produced
264	// so far, and how much of each policy's cap is still available.
265	interface ScenarioState {
266	  readonly results: readonly StepResult[];
267	  readonly remainingCaps: readonly number[];
268	}
269	
270	const initialStateOf = (policies: readonly QuoteStep[]): ScenarioState => ({
271	  results: [],
272	  remainingCaps: policies.map((policy) => capOf(policy.items)),
273	});
274	
275	const capsAfterClaim = (
276	  remainingCaps: readonly number[],
277	  policy: number,
278	  remainingCap: number,
279	): readonly number[] =>
280	  remainingCaps.map((cap, index) => (index === policy ? remainingCap : cap));
281	
282	const stateAfterQuote = (
283	  state: ScenarioState,
284	  result: QuoteResult,
285	): ScenarioState => ({ ...state, results: [...state.results, result] });
286	
287	const stateAfterClaim = (
288	  state: ScenarioState,
289	  step: ClaimStep,
290	  result: ClaimResult,
291	): ScenarioState => ({
292	  results: [...state.results, result],
293	  remainingCaps: capsAfterClaim(
294	    state.remainingCaps,
295	    step.policy,
296	    result.remainingCap,
297	  ),
298	});
299	
300	export const runScenario = (scenario: Scenario): ScenarioResult => {
301	  const policies = quoteStepsOf(scenario.steps);
302	
303	  const { results } = scenario.steps.reduce(
304	    (state, step, stepIndex) =>
305	      isQuoteStep(step)
306	        ? stateAfterQuote(
307	            state,
308	            quoteResultOf(
309	              step,
310	              scenario.customer,
311	              quoteStepsBefore(scenario.steps, stepIndex),
312	            ),
313	          )
314	        : stateAfterClaim(
315	            state,
316	            step,
317	            claimResultOf(step, policies, state.remainingCaps[step.policy]),
318	          ),
319	    initialStateOf(policies),
320	  );
321	
322	  return { results };
323	};
